/* Focused regression check for explicit child axis pattern compilation.
 * Builds against the supplied target libxml2 (no system libxml2).
 * Prints, for each element node, whether it matches a given pattern.
 * Exits non-zero on API failure.
 */
#include <stdio.h>
#include <string.h>
#include <libxml/parser.h>
#include <libxml/tree.h>
#include <libxml/pattern.h>

static int failures = 0;

static void
walk(xmlNodePtr node, xmlPatternPtr pat, const char *patstr)
{
    for (; node != NULL; node = node->next) {
        if (node->type == XML_ELEMENT_NODE) {
            int m = xmlPatternMatch(pat, node);
            xmlChar *path = xmlGetNodePath(node);
            printf("pattern=%s node=%s match=%d\n", patstr,
                   path ? (const char *) path : "?", m);
            if (path != NULL)
                xmlFree(path);
        }
        walk(node->children, pat, patstr);
    }
}

static int
run(const char *patstr, const char *xmlfile)
{
    xmlDocPtr doc;
    xmlPatternPtr pat;
    const xmlChar *namespaces[2] = { NULL, NULL };

    doc = xmlReadFile(xmlfile, NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "failed to parse %s\n", xmlfile);
        return -1;
    }
    pat = xmlPatterncompile((const xmlChar *) patstr, doc->dict, 0, namespaces);
    if (pat == NULL) {
        fprintf(stderr, "failed to compile pattern %s\n", patstr);
        xmlFreeDoc(doc);
        return -1;
    }
    walk(xmlDocGetRootElement(doc), pat, patstr);
    xmlFreePattern(pat);
    xmlFreeDoc(doc);
    return 0;
}

int
main(int argc, char **argv)
{
    int i;
    if (argc < 3) {
        fprintf(stderr, "usage: %s <xmlfile> <pattern> [pattern...]\n", argv[0]);
        return 2;
    }
    for (i = 2; i < argc; i++) {
        if (run(argv[i], argv[1]) != 0)
            failures++;
    }
    xmlCleanupParser();
    return failures == 0 ? 0 : 1;
}

/* Differential check: xmlPatternMatch vs the streaming pattern API for the
 * explicit child axis. Mirrors runtest.c's patternNode() consistency check.
 * Returns non-zero if the two APIs disagree or a stream call fails.
 */
#include <stdio.h>
#include <string.h>
#include <libxml/parser.h>
#include <libxml/tree.h>
#include <libxml/reader.h>
#include <libxml/pattern.h>

static int disagreements = 0;
static int errors = 0;

static void
walk(xmlTextReaderPtr reader, xmlPatternPtr pat,
     xmlStreamCtxtPtr stream, const char *patstr)
{
    int type = xmlTextReaderNodeType(reader);
    int empty = xmlTextReaderIsEmptyElement(reader);
    int match = -1;

    if (type == XML_READER_TYPE_ELEMENT) {
        xmlNodePtr cur = xmlTextReaderCurrentNode(reader);
        xmlChar *path;
        match = xmlPatternMatch(pat, cur);
        if (stream != NULL) {
            int ret = xmlStreamPush(stream,
                                    xmlTextReaderConstLocalName(reader),
                                    xmlTextReaderConstNamespaceUri(reader));
            if (ret < 0) {
                fprintf(stderr, "xmlStreamPush() failure for %s\n", patstr);
                errors++;
            } else if (ret != match) {
                path = xmlGetNodePath(cur);
                printf("DISAGREE pattern=%s node=%s match=%d stream=%d\n",
                       patstr, path ? (const char *) path : "?", match, ret);
                if (path != NULL)
                    xmlFree(path);
                disagreements++;
            }
        }
    }
    if (stream != NULL &&
        (type == XML_READER_TYPE_END_ELEMENT ||
         (type == XML_READER_TYPE_ELEMENT && empty))) {
        if (xmlStreamPop(stream) < 0) {
            fprintf(stderr, "xmlStreamPop() failure for %s\n", patstr);
            errors++;
        }
    }
}

static int
run(const char *patstr, const char *xmlfile)
{
    xmlDocPtr doc;
    xmlPatternPtr pat;
    xmlStreamCtxtPtr stream = NULL;
    xmlTextReaderPtr reader;
    const xmlChar *namespaces[2] = { NULL, NULL };
    int res;

    doc = xmlReadFile(xmlfile, NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "failed to parse %s\n", xmlfile);
        return -1;
    }
    pat = xmlPatterncompile((const xmlChar *) patstr, doc->dict, 0, namespaces);
    if (pat == NULL) {
        fprintf(stderr, "failed to compile pattern %s\n", patstr);
        xmlFreeDoc(doc);
        return -1;
    }
    stream = xmlPatternGetStreamCtxt(pat);
    if (stream != NULL) {
        if (xmlStreamPush(stream, NULL, NULL) < 0) {
            fprintf(stderr, "initial xmlStreamPush() failure\n");
            errors++;
        }
    }
    reader = xmlReaderWalker(doc);
    res = xmlTextReaderRead(reader);
    while (res == 1) {
        walk(reader, pat, stream, patstr);
        res = xmlTextReaderRead(reader);
    }
    if (res != 0) {
        fprintf(stderr, "walker failed\n");
        errors++;
    }
    xmlFreeTextReader(reader);
    xmlFreeStreamCtxt(stream);
    xmlFreePattern(pat);
    xmlFreeDoc(doc);
    return 0;
}

int
main(int argc, char **argv)
{
    int i;
    if (argc < 3) {
        fprintf(stderr, "usage: %s <xmlfile> <pattern> [pattern...]\n", argv[0]);
        return 2;
    }
    for (i = 2; i < argc; i++)
        run(argv[i], argv[1]);
    xmlCleanupParser();
    printf("disagreements=%d errors=%d\n", disagreements, errors);
    return (disagreements == 0 && errors == 0) ? 0 : 1;
}

